func locationUpdates(manager: CLLocationManager) -> AsyncStream<CLLocation> {
    AsyncStream(bufferingPolicy: .bufferingNewest(1)) { continuation in
        let delegate = LocationDelegate { continuation.yield($0) }
        manager.delegate = delegate
        manager.startUpdatingLocation()
        continuation.onTermination = { _ in
            manager.stopUpdatingLocation()
            _ = delegate                      // keep alive until the end
        }
    }
}

// SwiftUI: cancelled automatically when the view disappears
.task {
    for await location in locationUpdates(manager: manager) {
        model.update(location)
    }
}
